def _predict_np(model, X, device, batch):
    model.eval()
    out = []
    Xt = torch.tensor(X, dtype=torch.float32, device=device)
    for s in range(0, len(Xt), batch):
        out.append(torch.sigmoid(model(Xt[s:s + batch])).cpu().numpy())
    return np.concatenate(out)


class TorchWrapper:
    """Small wrapper so the solver can call `predict_proba` on the model."""

    def __init__(self, model, device="cuda"):
        self.model = model
        self.device = device

    def predict_proba(self, X):
        with torch.no_grad():
            self.model.eval()
            Xt = torch.tensor(np.asarray(X, np.float32), device=self.device)
            out = []
            for s in range(0, len(Xt), 1 << 18):
                out.append(torch.sigmoid(self.model(Xt[s:s + (1 << 18)])).cpu().numpy())
            return np.concatenate(out)

