{"arguments":{"content":""""Experiment: merge-aware DBSCAN for s5.

Instead of plain DBSCAN, run DBSCAN with a small eps to find dense cores
(without merges), then merge core-clusters whose KDE peaks are close,
finally absorb remaining points by density.
"""
import glob, os, sys
import numpy as np, pandas as pd
from sklearn.cluster import DBSCAN

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from metrics import all_metrics

DATA = "/task/problem/data"
FILES = {
    "scenario_5_blinking": "highden_DetectionList_*.csv",
    "scenario_8_blinking": "diffden_DetectionList*.csv",
}


def core_cluster(xy, eps, ms):
    lab = DBSCAN(eps=eps, min_samples=ms).fit(xy).labels_.astype(int)
    return lab


def merge_near(xy, lab, dist_thr, min_gain=1.0):
    """Merge clusters whose centroids are closer than dist_thr."""
    ids = np.unique(lab[lab > 0])
    if len(ids) < 2:
        return lab
    cents = {i: xy[lab == i].mean(0) for i in ids}
    # union-find
    parent = {i: i for i in ids}

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    order = sorted([(np.linalg.norm(cents[a] - cents[b]), a, b)
                    for ai, a in enumerate(ids) for b in ids[ai + 1:]])
    for d, a, b in order:
        if d > dist_thr:
            break
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    out = lab.copy()
    remap = {i: find(i) for i in ids}
    # renumber
    roots = sorted(set(remap.values()))
    rmap = {r: n + 1 for n, r in enumerate(roots)}
    for i in ids:
        out[lab == i] = rmap[remap[i]]
    return out


if __name__ == "__main__":
    inst = sys.argv[1]
    eps_list = [float(x) for x in sys.argv[2].split(",")]
    ms = int(sys.argv[3])
    thr_list = [float(x) for x in sys.argv[4].split(",")]
    fovs = []
    for f in sorted(glob.glob(os.path.join(DATA, inst, "train", FILES[inst]))):
        d = pd.read_csv(f)
        fovs.append((d[["x", "y"]].to_numpy(float), d["index"].to_numpy(int)))
    for eps in eps_list:
        for thr in thr_list:
            rows = []
            for xy, gt in fovs:
                lab = core_cluster(xy, eps, ms)
                lab = merge_near(xy, lab, thr)
                out = np.zeros(len(lab), dtype=int)
                for new, v in enumerate(np.unique(lab[lab > 0]), start=1):
                    out[lab == v] = new
                m = all_metrics(gt, out, xy)
                rows.append((m["ARI_r"], m["ARI_c"], m["ARI"]))
            a = np.array(rows)
            print(f"eps={eps:5.1f} ms={ms} thr={thr:5.1f}: "
                  f"ari_r={a[:,0].mean():.4f} ari_c={a[:,1].mean():.4f} "
                  f"ari={a[:,2].mean():.4f}", flush=True)
","file_path":"/workspace/exp_merge.py"},"name":"Write"}

{"arguments":{"content":""""Final hypothesis: ARI_r = harmonic mean over gt clusters of per-cluster
BINARY RAND index (not adjusted), with reduced weight on background.
Also try arithmetic means and geometric means.
