import glob, os, itertools
import numpy as np, pandas as pd
from sklearn.cluster import DBSCAN
from sklearn.metrics import rand_score

DATA = "/task/problem/data"
FILES = {
    "scenario_5_blinking": "highden_DetectionList_*.csv",
    "scenario_6_blinking": "elliptical_w_noise_DetectionList_*.csv",
    "scenario_8_blinking": "diffden_DetectionList*.csv",
    "scenario_8_no_blinking": "diffden_MoleculeList_*.csv",
}
DB = {
    "scenario_5_blinking": dict(eps=24.0, min_samples=15),
    "scenario_6_blinking": dict(eps=40.0, min_samples=40),
    "scenario_8_blinking": dict(eps=35.0, min_samples=10),
    "scenario_8_no_blinking": dict(eps=50.0, min_samples=5),
}
OFFICIAL = {"scenario_5_blinking": 0.661, "scenario_6_blinking": 0.656,
            "scenario_8_blinking": 0.868, "scenario_8_no_blinking": 0.805}


def dbscan_labels(xy, cfg):
    lab = DBSCAN(**cfg).fit(xy).labels_.astype(int)
    out = np.zeros(len(lab), dtype=int)
    for new, v in enumerate(np.unique(lab[lab > 0]), start=1):
        out[lab == v] = new
    return out


def per_cluster_rand(gt, pred, bg_w=0.25):
    sc, w = [], []
    for c in np.unique(gt):
        m = gt == c
        vals, cnts = np.unique(pred[m], return_counts=True)
        pl = vals[np.argmax(cnts)]
        sc.append(rand_score(m.astype(int), (pred == pl).astype(int)))
        w.append(m.sum() * (bg_w if c == 0 else 1.0))
    return np.array(sc), np.array(w)


def per_cluster_fmi(gt, pred, bg_w=0.25):
    from sklearn.metrics import fowlkers_mallows_score
    sc, w = [], []
    for c in np.unique(gt):
        m = gt == c
        vals, cnts = np.unique(pred[m], return_counts=True)
        pl = vals[np.argmax(cnts)]
        sc.append(fowlkers_mallows_score(m.astype(int), (pred == pl).astype(int)))
        w.append(m.sum() * (bg_w if c == 0 else 1.0))
    return np.array(sc), np.array(w)


if __name__ == "__main__":
    for inst in FILES:
        res = {}
        for f in sorted(glob.glob(os.path.join(DATA, inst, "train", FILES[inst]))):
            d = pd.read_csv(f)
            xy = d[["x", "y"]].to_numpy(float)
            gt = d["index"].to_numpy(int)
            pred = dbscan_labels(xy, DB[inst])
            for name, fn in [("rand", per_cluster_rand), ("fmi", per_cluster_fmi)]:
                s, w = fn(gt, pred)
                for agg in ["harm", "arith", "geo"]:
                    k = f"{name}|{agg}"
                    if agg == "harm":
                        v = w.sum() / (w / np.clip(s, 1e-9, None)).sum()
                    elif agg == "arith":
                        v = (w * s).sum() / w.sum()
                    else:
                        v = np.exp((w * np.log(np.clip(s, 1e-9, None))).sum() / w.sum())
                    res.setdefault(k, []).append(v)
        print(f"{inst} (official {OFFICIAL[inst]:.3f}): " +
              " ".join(f"{k}={np.mean(v):.3f}" for k, v in res.items()))
","file_path":"/workspace/probe_arir5.py"},"name":"Write"}

{"arguments":{"content":""""Systematic ARI_r search: enumerate implementations of 'harmonic mean of
per-cluster ARI contributions with reduced background weight' and test against
the official scores computed on TRAIN FOVs (same distribution as test).

Official test scores for tuned DBSCAN: s5 .661 s6 .656 s8b .868 s8n .805.
A train FOV score should be in the same ballpark (per-FOV variance exists).

Candidate axis:
  per-cluster score s_c:
    a) ARI(gt==c binary, pred full multiclass)
    b) ARI(gt==c, pred==majority)  [binary-binary]
    c) ARI restricted to points of cluster c plus points of matched pred
    d) F1(gt==c, pred==majority)
  aggregate: harmonic mean with weights n_c (bg weight x beta)
  beta in {0.25, 0.5, 1.0}
"""
import glob, os, itertools
import numpy as np, pandas as pd
from sklearn.cluster import DBSCAN
from sklearn.metrics import adjusted_rand_score

DATA = "/task/problem/data"
FILES = {
    "scenario_5_blinking": "highden_DetectionList_*.csv",
    "scenario_6_blinking": "elliptical_w_noise_DetectionList_*.csv",
    "scenario_8_blinking": "diffden_DetectionList*.csv",
    "scenario_8_no_blinking": "diffden_MoleculeList_*.csv",
}
DB = {
    "scenario_5_blinking": dict(eps=24.0, min_samples=15),
    "scenario_6_blinking": dict(eps=40.0, min_samples=40),
    "scenario_8_blinking": dict(eps=35.0, min_samples=10),
    "scenario_8_no_blinking": dict(eps=50.0, min_samples=5),
}
OFFICIAL = {"scenario_5_blinking": 0.661, "scenario_6_blinking": 0.656,
            "scenario_8_blinking": 0.868, "scenario_8_no_blinking": 0.805}


def dbscan_labels(xy, cfg):
    lab = DBSCAN(**cfg).fit(xy).labels_.astype(int)
    out = np.zeros(len(lab), dtype=int)
    for new, v in enumerate(np.unique(lab[lab > 0]), start=1):
        out[lab == v] = new
    return out


def s_a(gt, pred, c):
    return adjusted_rand_score((gt == c).astype(int), pred)


def s_b(gt, pred, c):
    m = gt == c
    vals, cnts = np.unique(pred[m], return_counts=True)
    pl = vals[np.argmax(cnts)]
    return adjusted_rand_score(m.astype(int), (pred == pl).astype(int))


def s_c(gt, pred, c):
    m = gt == c
    vals, cnts = np.unique(pred[m], return_counts=True)
    pl = vals[np.argmax(cnts)]
    keep = m | (pred == pl)
    return adjusted_rand_score(gt[keep], pred[keep])


def s_d(gt, pred, c):
    m = gt == c
    vals, cnts = np.unique(pred[m], return_counts=True)
    pl = vals[np.argmax(cnts)]
    rec = cnts.max() / m.sum()
    prec = (pred[m] == pl).sum() / max((pred == pl).sum(), 1)
    return 0.0 if prec + rec == 0 else 2 * prec * rec / (prec + rec)


SC = dict(a=s_a, b=s_b, c=s_c, d=s_d)


def agg(scores, weights, how="hm"):
    s = np.clip(np.asarray(scores, float), 1e-9, None)
    w = np.asarray(weights, float)
    if how == "hm":
        return w.sum() / (w / s).sum()
    if how == "am":
        return (w * s).sum() / w.sum()
    return float(np.exp((w * np.log(s)).sum() / w.sum()))


if __name__ == "__main__":
    res = {}
    per_fov = {}
    for inst in FILES:
        fov_scores = {k: [] for k in itertools.product(SC, ["hm", "am"], [0.25, 0.5, 1.0])}
        for f in sorted(glob.glob(os.path.join(DATA, inst, "train", FILES[inst]))):
            d = pd.read_csv(f)
            xy = d[["x", "y"]].to_numpy(float)
            gt = d["index"].to_numpy(int)
            pred = dbscan_labels(xy, DB[inst])
            for (sk, sfn), how, beta in itertools.product(SC.items(), ["hm", "am"],
                                                          [0.25, 0.5, 1.0]):
                sc, w = [], []
                for c in np.unique(gt):
                    sc.append(sfn(gt, pred, c))
                    w.append((gt == c).sum() * (beta if c == 0 else 1.0))
                fov_scores[(sk, how, beta)].append(agg(sc, w, how))
        for k, v in fov_scores.items():
            res.setdefault(k, {})[inst] = np.mean(v)

    print(f"{'key':24s} " + " ".join(f"{i.split('_')[1]:>7s}" for i in FILES) + "   official")
    for k, v in res.items():
        line = f"{str(k):24s} "
        for i in FILES:
            line += f"{v[i]:7.3f} "
        line += "  off: " + " ".join(f"{OFFICIAL[i]:.3f}" for i in FILES)
        # deviation from official profile
        dev = np.sqrt(np.mean([(v[i] - OFFICIAL[i]) ** 2 for i in FILES]))
        print(line + f"  rmse={dev:.3f}")
","file_path":"/workspace/probe_arir7.py"},"name":"Write"}

{"arguments":{"content":""""Sweep the background weight beta and the per-cluster-score variant closer,
with per-gt-cluster and per-pred-cluster symmetric averaging, matching the
official profile (s5 .661 s6 .656 s8b .868 s8n .805).
"""
import glob, os, itertools
import numpy as np, pandas as pd
from sklearn.cluster import DBSCAN

DATA = "/task/problem/data"
FILES = {
    "scenario_5_blinking": "highden_DetectionList_*.csv",
    "scenario_6_blinking": "elliptical_w_noise_DetectionList_*.csv",
    "scenario_8_blinking": "diffden_DetectionList*.csv",
    "scenario_8_no_blinking": "diffden_MoleculeList_*.csv",
}
DB = {
    "scenario_5_blinking": dict(eps=24.0, min_samples=15),
    "scenario_6_blinking": dict(eps=40.0, min_samples=40),
    "scenario_8_blinking": dict(eps=35.0, min_samples=10),
    "scenario_8_no_blinking": dict(eps=50.0, min_samples=5),
}
OFFICIAL = {"scenario_5_blinking": 0.661, "scenario_6_blinking": 0.656,
            "scenario_8_blinking": 0.868, "scenario_8_no_blinking": 0.805}


def dbscan_labels(xy, cfg):
    lab = DBSCAN(**cfg).fit(xy).labels_.astype(int)
    out = np.zeros(len(lab), dtype=int)
    for new, v in enumerate(np.unique(lab[lab > 0]), start=1):
        out[lab == v] = new
    return out


def f1_of(mask_gt, mask_pd):
    n1, n2 = mask_gt.sum(), mask_pd.sum()
    inter = (mask_gt & mask_pd).sum()
    if n1 + n2 == 0:
        return 1.0
    return 2 * inter / (n1 + n2)


def per_cluster_f(gt, pred, beta, side="gt"):
    src = gt if side == "gt" else pred
    other = pred if side == "gt" else gt
    sc, w = [], []
    for c in np.unique(src):
        m = src == c
        vals, cnts = np.unique(other[m], return_counts=True)
        pl = vals[np.argmax(cnts)]
        sc.append(f1_of(m, other == pl))
        w.append(m.sum() * (beta if (c == 0 or pl == 0) else 1.0))
    return np.array(sc), np.array(w)


if __name__ == "__main__":
    betas = [0.0, 0.1, 0.15, 0.2, 0.25, 0.3, 0.4]
    rows = []
    for beta in betas:
        for sides in ["gt", "pred", "both"]:
            res = {}
            for inst in FILES:
                vals = []
                for f in sorted(glob.glob(os.path.join(DATA, inst, "train", FILES[inst]))):
                    d = pd.read_csv(f)
                    xy = d[["x", "y"]].to_numpy(float)
                    gt = d["index"].to_numpy(int)
                    pred = dbscan_labels(xy, DB[inst])
                    if sides == "both":
                        s1, w1 = per_cluster_f(gt, pred, beta, "gt")
                        s2, w2 = per_cluster_f(gt, pred, beta, "pred")
                        s, w = np.concatenate([s1, s2]), np.concatenate([w1, w2])
                    else:
                        s, w = per_cluster_f(gt, pred, beta, sides)
                    s = np.clip(s, 1e-9, None)
                    vals.append(w.sum() / (w / s).sum())
                res[inst] = np.mean(vals)
            dev = np.sqrt(np.mean([(res[i] - OFFICIAL[i]) ** 2 for i in FILES]))
            rows.append((beta, sides, dev, res))
    rows.sort(key=lambda r: r[2])
    for beta, sides, dev, res in rows[:10]:
        print(f"beta={beta:.2f} sides={sides:5s} rmse={dev:.4f} " +
              " ".join(f"{res[i]:.3f}" for i in FILES))
","file_path":"/workspace/probe_arir8.py"},"name":"Write"}

