import os, sys, json
import numpy as np
sys.path.insert(0, '/workspace')
from exp import INSTANCES, load, lognorm, spatial_graph, smooth
from sklearn.decomposition import PCA
from sklearn.cluster import KMeans

results = {}
for inst in INSTANCES:
    a, b = load(inst)
    R = lognorm(a.layers['counts'])
    A = lognorm(b.layers['counts'])
    sp = a.obsm['spatial']
    for nn in [5, 6, 7, 9]:
        S = spatial_graph(sp, k=nn)
        for reps in [1, 2]:
            Rs = smooth(S, R, reps); As = smooth(S, A, reps)
            PRs = {}
            PAs = {}
            for nr in [4, 6, 10, 15, 20]:
                PRs[nr] = PCA(nr, random_state=0).fit_transform(Rs)
                PRs[nr] /= (PRs[nr].std(0) + 1e-9)
            for na in [4, 6, 8, 10, 20]:
                PAs[na] = PCA(na, random_state=0).fit_transform(As)
                PAs[na] /= (PAs[na].std(0) + 1e-9)
            for nr in [4, 6, 10, 15, 20]:
                for na in [4, 6, 8, 10, 20]:
                    for w in [0.7, 1.0, 1.5]:
                        Z = np.hstack([PRs[nr], w * PAs[na]])
                        Z /= np.sqrt((Z**2).sum(1, keepdims=True)) + 1e-9
                        lab = KMeans(5, n_init=10, random_state=0).fit_predict(Z)
                        results[(inst, nn, reps, nr, na, w)] = lab
np.save('/tmp/grid2.npy', results)
print('done', len(results))
