{"arguments":{"content":""""Data loading utilities for protein variant effect prediction."""
import os
import re
import numpy as np
import pandas as pd

AA_ORDER = "ACDEFGHIKLMNPQRSTVWY"
AA_TO_IDX = {a: i for i, a in enumerate(AA_ORDER)}

INSTANCES = [
    "gfp", "gb1", "dlg4_abundance", "dlg4_binding", "grb2_abundance",
    "grb2_binding", "pab1", "pten_abundance", "pten_activity", "tem_1", "ube4b",
]

_MUT_RE = re.compile(r"^([A-Z])(\d+)([A-Z])$")


def parse_variant(variant):
    """Parse 'A2G,K3R' -> [(2,'A','G'), (3,'K','R')]. Zero-based positions."""
    out = []
    for tok in str(variant).split(","):
        tok = tok.strip()
        if not tok:
            continue
        m = _MUT_RE.match(tok)
        if m is None:
            raise ValueError(f"bad mutation token: {tok!r} in {variant!r}")
        out.append((int(m.group(2)), m.group(1), m.group(3)))
    return out


def load_instance(data_dir, instance):
    """Return dict with train/test frames, wild-type sequence and metadata."""
    d = os.path.join(data_dir, instance)
    train = pd.read_csv(os.path.join(d, "train.tsv"), sep="\t")
    test = pd.read_csv(os.path.join(d, "test.tsv"), sep="\t")

    # Recover wild-type residues: every mutated position shows its original AA.
    wt = {}
    nmut_train = np.zeros(len(train), dtype=np.int64)
    muts_train = []
    for i, v in enumerate(train["variant"].values):
        ms = parse_variant(v)
        muts_train.append(ms)
        nmut_train[i] = len(ms)
        for p, a, b in ms:
            wt[p] = a
    muts_test = []
    nmut_test = np.zeros(len(test), dtype=np.int64)
    for i, v in enumerate(test["variant"].values):
        ms = parse_variant(v)
        muts_test.append(ms)
        nmut_test[i] = len(ms)
        for p, a, b in ms:
            wt.setdefault(p, a)

    pos_min, pos_max = min(wt), max(wt)
    # Fill gaps with 'X' (unknown) so index -> sequence mapping stays dense.
    seq = "".join(wt.get(p, "X") for p in range(pos_min, pos_max + 1))

    def to_global(ms):
        return [(p - pos_min, a, b) for p, a, b in ms]

    return {
        "instance": instance,
        "dir": d,
        "train": train,
        "test": test,
        "wt_seq": seq,
        "offset": pos_min,
        "muts_train": [to_global(m) for m in muts_train],
        "muts_test": [to_global(m) for m in muts_test],
        "L": len(seq),
    }


def apply_mutations(seq, muts):
    """Apply (zero-based position, wt, mutant) mutations to a sequence."""
    s = list(seq)
    for p, a, b in muts:
        if p < len(s) and s[p] == a:
            s[p] = b
    return "".join(s)


def variant_to_indices(muts, L):
    """Mutation list -> array of (position, mutant_aa_index) rows."""
    return [(p, AA_TO_IDX[b]) for p, _a, b in muts]


def pdb_path(inst_dir):
    for f in os.listdir(inst_dir):
        if f.endswith(".pdb"):
            return os.path.join(inst_dir, f)
    return None
