from collections import defaultdict

def add2(inst):
    y = inst['train']['score'].values.astype(np.float32)
    glob = y.mean()
    posd = defaultdict(list); aad = defaultdict(list)
    for i,ms in enumerate(inst['muts_train']):
        for p,a,b in ms:
            posd[p].append(y[i]); aad[b].append(y[i])
    def shrink(v,k=5.0): return (np.mean(v)*len(v)+glob*k)/(len(v)+k)
    posm = {p:shrink(v) for p,v in posd.items()}
    aam  = {b:shrink(v) for b,v in aad.items()}
    pm = np.mean([abs(v-glob) for v in posm.values()])
    am = np.mean([abs(v-glob) for v in aam.values()])
