{"arguments":{"content":""""Feature extraction: RDKit Morgan fingerprints + molecular descriptors."""
import numpy as np
from rdkit import Chem, DataStructs
from rdkit.Chem import AllChem, Descriptors, rdMolDescriptors


def mol_from_smiles(smi):
    try:
        m = Chem.MolFromSmiles(str(smi))
        return m
    except Exception:
        return None


_FP_DIM = 2048


def morgan_count_fps(smiles_list, radius=2, dim=_FP_DIM, use_counts=True):
    """Count-based Morgan fingerprints (folded)."""
    n = len(smiles_list)
    X = np.zeros((n, dim), dtype=np.float32)
    for i, smi in enumerate(smiles_list):
        m = mol_from_smiles(smi)
        if m is None:
            continue
        bv = AllChem.GetMorganFingerprint(m, radius)
        if use_counts:
            for k, v in bv.GetNonzeroElements().items():
                X[i, hash(k) % dim] += v
        else:
            fp = AllChem.GetMorganFingerprintAsBitVect(m, radius, nBits=dim)
            arr = np.zeros((dim,), dtype=np.float32)
            DataStructs.ConvertToNumpyArray(fp, arr)
            X[i] = arr
    return X


_DESC_FUNCS = None


def rdkit_descriptors(smiles_list):
    """Small set of physicochemical descriptors (scaled later)."""
    global _DESC_FUNCS
    if _DESC_FUNCS is None:
        from rdkit.ML.Descriptors import MoleculeDescriptors
        names = [n for n, _ in Descriptors._descList][:200]
        _DESC_FUNCS = MoleculeDescriptors.MolecularDescriptorCalculator(names)
        _DESC_FUNCS.names = names
    n = len(smiles_list)
    D = np.zeros((n, len(_DESC_FUNCS.names)), dtype=np.float32)
    for i, smi in enumerate(smiles_list):
        m = mol_from_smiles(smi)
        if m is None:
            continue
        try:
            vals = _DESC_FUNCS.CalcDescriptors(m)
            D[i] = [0.0 if (v is None or (isinstance(v, float) and not np.isfinite(v))) else v
                    for v in vals]
        except Exception:
            continue
    return D


def atom_counts(smiles_list):
    """Element-count features: useful linear signal for QM targets."""
    import collections
    from rdkit import Chem
    elems = ['C', 'N', 'O', 'F', 'S', 'Cl', 'Br', 'I', 'P', 'B', 'Si', 'H',
             'Na', 'K', 'Li', 'Ca', 'Zn', 'Fe', 'Mg', 'Cu']
    n = len(smiles_list)
    D = np.zeros((n, len(elems) + 3), dtype=np.float32)
    idx = {e: j for j, e in enumerate(elems)}
    for i, smi in enumerate(smiles_list):
        m = mol_from_smiles(smi)
        if m is None:
            continue
        mH = Chem.AddHs(m)
        c = collections.Counter(a.GetSymbol() for a in mH.GetAtoms())
        for e, v in c.items():
            if e in idx:
                D[i, idx[e]] = v
        D[i, len(elems)] = mH.GetNumAtoms()
        D[i, len(elems) + 1] = mH.GetNumBonds()
        try:
            D[i, len(elems) + 2] = float(rdMolDescriptors.CalcExactMolWt(m))
        except Exception:
            pass
    return D


def build_features(smiles_list, kind="fp"):
    if kind == "fp":
        return morgan_count_fps(smiles_list)
    if kind == "fp+desc":
        return np.hstack([morgan_count_fps(smiles_list), rdkit_descriptors(smiles_list)])
    if kind == "atom":
        return atom_counts(smiles_list)
    raise ValueError(kind)
