{"arguments":{"content":"/* Shared C core for MaxCut and MIS local search.
 *
 * Data layout: CSR adjacency arrays (flat neighbor list + row offsets) built
 * once per graph on the Python side.
 */
#include <stdlib.h>
#include <string.h>
#include <math.h>

/* xoshiro256** portable PRNG */
typedef struct { unsigned long long s[4]; } rng_t;

static inline unsigned long long rotl(const unsigned long long x, int k) {
    return (x << k) | (x >> (64 - k));
}

static unsigned long long next_u64(rng_t *r) {
    unsigned long long *s = r->s;
    const unsigned long long result = rotl(s[1] * 5, 7) * 9;
    const unsigned long long t = s[1] << 17;
    s[2] ^= s[0];
    s[3] ^= s[1];
    s[1] ^= s[2];
    s[0] ^= s[3];
    s[2] ^= t;
    s[3] = rotl(s[3], 45);
    return result;
}

static inline unsigned int next_u32(rng_t *r) {
    return (unsigned int)(next_u64(r) >> 32);
}

/* uniform in [0, bound) */
static inline unsigned int rnd_bound(rng_t *r, unsigned int bound) {
    /* Lemire's method with rejection */
    unsigned long long m = (unsigned long long)next_u32(r) * (unsigned long long)bound;
    unsigned int l = (unsigned int)m;
    if (l < bound) {
        unsigned int t = (unsigned int)(-bound) % bound;
        while (l < t) {
            m = (unsigned long long)next_u32(r) * (unsigned long long)bound;
            l = (unsigned int)m;
        }
    }
    return (unsigned int)(m >> 32);
}

static void seed_rng(rng_t *r, unsigned long long seed) {
    for (int i = 0; i < 4; i++) {
        seed += 0x9E3779B97F4A7C15ULL;
        unsigned long long z = seed;
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
        z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
        r->s[i] = z ^ (z >> 31);
    }
    for (int i = 0; i < 16; i++) next_u64(r);
}

/* ---------------- MaxCut ---------------- */

typedef struct {
    const int *adj_start;   /* n+1 */
    const int *adj_flat;    /* 2m */
    const int *eu;
    const int *ev;
    int n, m;
} mc_graph_t;

static inline int num_internal_neighbors(const mc_graph_t *g, const int *x,
                                         int v) {
    int c = 0;
    int s = g->adj_start[v], e = g->adj_start[v + 1];
    for (int i = s; i < e; i++)
        if (x[g->adj_flat[i]]) c++;
    return c;
}

/* One pass of Chuangchunsong's greedy for MaxCut.
 * x: binary array, w: scratch buffer of size 2n (counts in same/other part).
 * Returns 1 if any flip happened. */
int mc_greedy_pass(const mc_graph_t *g, int *x, int *w, rng_t *rng) {
    int n = g->n;
    int *same = w;          /* count of neighbors with same label */
    int *other = w + n;     /* count of neighbors with other label */
    for (int v = 0; v < n; v++) {
        same[v] = 0;
        other[v] = 0;
    }
    for (int e = 0; e < g->m; e++) {
        int u = g->eu[e], v = g->ev[e];
        if (x[u] == x[v]) { same[u]++; same[v]++; }
        else { other[u]++; other[v]++; }
    }
    int *order = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) order[i] = i;
    for (int i = n - 1; i > 0; i--) {
        int j = rnd_bound(rng, i + 1);
        int t = order[i]; order[i] = order[j]; order[j] = t;
    }
    int moved = 0;
    for (int k = 0; k < n; k++) {
        int v = order[k];
        if (x[v] == 0) {
            if (other[v] < same[v]) {
                x[v] = 1;
                moved = 1;
                int s = g->adj_start[v], e = g->adj_start[v + 1];
                for (int i = s; i < e; i++) {
                    int u = g->adj_flat[i];
                    if (x[u] == 0) { same[u]++; other[u]--; }
                    else { same[u]--; other[u]++; }
                }
            }
        } else {
            if (same[v] < other[v]) {
                x[v] = 0;
                moved = 1;
                int s = g->adj_start[v], e = g->adj_start[v + 1];
                for (int i = s; i < e; i++) {
                    int u = g->adj_flat[i];
                    if (x[u] == 1) { same[u]++; other[u]--; }
                    else { same[u]--; other[u]++; }
                }
            }
        }
    }
    free(order);
    return moved;
}

int mc_solve(const int *adj_start, const int *adj_flat, const int *eu,
             const int *ev, int n, int m, int T, int max_passes,
             unsigned long long seed, int *best_x) {
    mc_graph_t g;
    g.adj_start = adj_start;
    g.adj_flat = adj_flat;
    g.eu = eu;
    g.ev = ev;
    g.n = n;
    g.m = m;

    rng_t rng;
    seed_rng(&rng, seed);

    int *x = (int *)calloc(n, sizeof(int));
    int *w = (int *)calloc(2 * n, sizeof(int));
    if (!x || !w) return -1;

    int best_score = -1;
    for (int t = 0; t < T; t++) {
        for (int v = 0; v < n; v++) x[v] = (int)(next_u64(&rng) & 1ULL);
        int passes = 0;
        while (passes < max_passes && mc_greedy_pass(&g, x, w, &rng)) passes++;
        int score = 0;
        for (int e = 0; e < m; e++) score += (x[eu[e]] != x[ev[e]]);
        if (score > best_score) {
            best_score = score;
            memcpy(best_x, x, sizeof(int) * n);
        }
    }
    free(x);
    free(w);
    return best_score;
}

/* ---------------- MIS ---------------- */

/* Greedy initial solution (used when x is all-zero). */
static void mis_greedy_init(const mc_graph_t *g, int *x, rng_t *rng) {
    int n = g->n;
    for (int i = 0; i < n; i++) x[i] = 1;
    /* random priority greedy removal: repeatedly pick a random remaining
     * vertex, keep it, remove its neighbours. */
    int *avail = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) avail[i] = 1;
    int remaining = n;
    while (remaining > 0) {
        int idx = rnd_bound(rng, remaining);
        int cnt = 0, v = -1;
        for (int i = 0; i < n; i++) {
            if (avail[i]) {
                if (cnt == idx) { v = i; break; }
                cnt++;
            }
        }
        if (v < 0) break;
        x[v] = 0; /* 0 means "in independent set" */
        avail[v] = 0;
        remaining--;
        int s = g->adj_start[v], e = g->adj_start[v + 1];
        for (int i = s; i < e; i++) {
            int u = g->adj_flat[i];
            if (avail[u]) { avail[u] = 0; remaining--; }
        }
    }
    free(avail);
}

/* (1,2)-swap local search for MIS. x: 0 = in independent set.
 * Returns number of accepted swaps. Performs up to max_rounds sweeps. */
static int mis_swap_pass(const mc_graph_t *g, int *x, int *sel,
                         int *nsel, rng_t *rng) {
    int n = g->n;
    int count = 0;
    int moves;
    do {
        moves = 0;
        int ns = 0;
        for (int v = 0; v < n; v++) if (x[v] == 0) sel[ns++] = v;
        *nsel = ns;
        for (int k = 0; k < ns; k++) {
            int v = sel[k];
            if (x[v] != 0) continue;
            /* collect free neighbours of v */
            int s = g->adj_start[v], e = g->adj_start[v + 1];
            int fn = 0;
            int f0 = -1, f1 = -1;
            for (int i = s; i < e; i++) {
                int u = g->adj_flat[i];
                if (x[u] == 1) {
                    if (fn == 0) f0 = u; else if (fn == 1) f1 = u;
                    fn++;
                }
            }
            if (fn != 2) continue;
            /* check non-adjacency of f0, f1 */
            int adj = 0;
            int s0 = g->adj_start[f0], e0 = g->adj_start[f0 + 1];
            for (int i = s0; i < e0; i++)
                if (g->adj_flat[i] == f1) { adj = 1; break; }
            if (adj) continue;
            x[v] = 1;
            x[f0] = 0;
            x[f1] = 0;
            moves++;
            count++;
        }
    } while (moves > 0 && count < 2000000000);
    return count;
}

/* One-armarus: iterated local search with vertex exclusion (k-restarts).
 * x0: 1 = candidate set (1 means NOT in IS initially). */
typedef struct {
    int *penalty;   /* exclusion counter per vertex */
} mis_state_t;

int mis_solve(const int *adj_start, const int *adj_flat, const int *eu,
              const int *ev, int n, int m, int T, int max_no_improve,
              unsigned long long seed, int *best_x) {
    mc_graph_t g;
    g.adj_start = adj_start;
    g.adj_flat = adj_flat;
    g.eu = eu;
    g.ev = ev;
    g.n = n;
    g.m = m;

    rng_t rng;
    seed_rng(&rng, seed);

    int *x = (int *)malloc(sizeof(int) * n);
    int *sel = (int *)malloc(sizeof(int) * n);
    int *w = (int *)calloc(2 * n, sizeof(int));
    int *penalty = (int *)calloc(n, sizeof(int));
    if (!x || !sel || !w || !penalty) return -1;

    int best_score = -1;
    /* Phase 1: greedy + swaps from a few random greedy starts */
    for (int t = 0; t < T; t++) {
        if (t == 0) {
            for (int i = 0; i < n; i++) x[i] = 0;
            /* start from empty IS, run greedy pass on all-one labels */
            for (int i = 0; i < n; i++) x[i] = 1;
        } else {
            for (int i = 0; i < n; i++) x[i] = (int)(next_u64(&rng) & 1ULL);
        }
        int passes = 0;
        while (passes < 8 && mc_greedy_pass(&g, x, w, &rng)) passes++;
        int ns;
        mis_swap_pass(&g, x, sel, &ns, &rng);
        int score = 0;
        for (int i = 0; i < n; i++) if (x[i] == 0) score++;
        if (score > best_score) {
            best_score = score;
            memcpy(best_x, x, sizeof(int) * n);
        }
    }

    /* Phase 2: iterated local search with forced exclusions (Andrade-style) */
    long long budget = 200LL * n + 20000LL;
    long long iter = 0;
    int no_improve = 0;
    memcpy(x, best_x, sizeof(int) * n);
    while (iter < budget && no_improve < max_no_improve) {
        iter++;
        /* pick a random vertex with penalty 0 to exclude */
        int tries = 0;
        int v = -1;
        while (tries < 64) {
            int c = (int)rnd_bound(&rng, (unsigned)n);
            if (penalty[c] == 0) { v = c; break; }
            tries++;
        }
        if (v < 0) break;
        penalty[v] = 1;
        /* greedy repair: start from current solution with v excluded */
        int passes = 0;
        while (passes < 3 && mc_greedy_pass(&g, x, w, &rng)) passes++;
        int ns;
        mis_swap_pass(&g, x, sel, &ns, &rng);
        int score = 0;
        for (int i = 0; i < n; i++) if (x[i] == 0) score++;
        if (score > best_score) {
            best_score = score;
            memcpy(best_x, x, sizeof(int) * n);
            no_improve = 0;
        } else {
            memcpy(x, best_x, sizeof(int) * n);
            no_imize_increase_fix: ;
            no_improve++;
        }
        /* decrement penalties periodically */
        if ((iter & 63) == 0) {
            for (int i = 0; i < n; i++)
                if (penalty[i] > 0) penalty[i]--;
        }
    }
    free(x);
    free(sel);
    free(w);
    free(penalty);
    return best_score;
}
