{"arguments":{"content":"/* C cores for MaxCut and Maximum Independent Set local search.
 *
 * Graphs are passed as CSR arrays (adj_start[n+1], adj_flat[2m]) plus the
 * edge list (eu[m], ev[m]).  All algorithms are randomized heuristics.
 */
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>

/* ------------------------------------------------------------------ */
/* xoshiro256** PRNG                                                    */
typedef struct { unsigned long long s[4]; } rng_t;

static inline unsigned long long rotl64(const unsigned long long x, int k) {
    return (x << k) | (x >> (64 - k));
}

static inline unsigned long long next_u64(rng_t *r) {
    unsigned long long *s = r->s;
    const unsigned long long result = rotl64(s[1] * 5, 7) * 9;
    const unsigned long long t = s[1] << 17;
    s[2] ^= s[0]; s[3] ^= s[1]; s[1] ^= s[2]; s[0] ^= s[3];
    s[2] ^= t;    s[3] = rotl64(s[3], 45);
    return result;
}

static inline unsigned int next_u32(rng_t *r) { return (unsigned)(next_u64(r) >> 32); }

/* uniform integer in [0, bound) -- Lemire's debiased method */
static inline unsigned int rnd_bound(rng_t *r, unsigned int bound) {
    unsigned long long m = (unsigned long long)next_u32(r) * (unsigned long long)bound;
    unsigned int l = (unsigned)m;
    if (l < bound) {
        unsigned int t = (unsigned)(-(int)bound) % bound;
        while (l < t) {
            m = (unsigned long long)next_u32(r) * (unsigned long long)bound;
            l = (unsigned)m;
        }
    }
    return (unsigned)(m >> 32);
}

static inline double rnd_double(rng_t *r) {
    return (double)(next_u64(r) >> 11) * (1.0 / 9007199254740992.0);
}

static void seed_rng(rng_t *r, unsigned long long seed) {
    for (int i = 0; i < 4; i++) {
        seed += 0x9E3779B97F4A7C15ULL;
        unsigned long long z = seed;
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
        z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
        r->s[i] = z ^ (z >> 31);
    }
    for (int i = 0; i < 16; i++) next_u64(r);
}

static double now_seconds(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + 1e-9 * (double)ts.tv_nsec;
}

typedef struct {
    int n, m;
    const int *adj_start;
    const int *adj_flat;
    const int *eu;
    const int *ev;
} graph_t;

/* ================================================================== */
/* ============================  MAXCUT  ============================= */
/* ================================================================== */
/*
 * Greedy "improved" pass in the sense of Chuangchunsong (2015): visit the
 * vertices in random order and flip a vertex when that strictly increases
 * the number of crossing edges, keeping same/other neighbour counts
 * incrementally up to date.  Returns the number of flips performed.
 */
static int mc_pass(const graph_t *g, int *x, int *same, int *other, rng_t *rng) {
    const int n = g->n, m = g->m;
    for (int v = 0; v < n; v++) { same[v] = 0; other[v] = 0; }
    for (int e = 0; e < m; e++) {
        const int u = g->eu[e], v = g->ev[e];
        if (x[u] == x[v]) { same[u]++; same[v]++; }
        else              { other[u]++; other[v]++; }
    }
    int *order = (int *)malloc(sizeof(int) * (size_t)n);
    for (int i = 0; i < n; i++) order[i] = i;
    for (int i = n - 1; i > 0; i--) {
        int j = (int)rnd_bound(rng, (unsigned)(i + 1));
        int t = order[i]; order[i] = order[j]; order[j] = t;
    }
    int moved = 0;
    for (int k = 0; k < n; k++) {
        const int v = order[k];
        if (x[v] == 0) {
            if (other[v] >= same[v]) continue;
            x[v] = 1; moved++;
        } else {
            if (same[v] >= other[v]) continue;
            x[v] = 0; moved++;
        }
        const int s = g->adj_start[v], e = g->adj_start[v + 1];
        for (int i = s; i < e; i++) {
            const int u = g->adj_flat[i];
            if (x[u] == x[v]) { same[u]++; other[u]--; }
            else              { same[u]--; other[u]++; }
        }
    }
    free(order);
    return moved;
}

static inline int mc_score(const graph_t *g, const int *x) {
    int c = 0;
    for (int e = 0; e < g->m; e++) c += (x[g->eu[e]] != x[g->ev[e]]);
    return c;
}

/* Multi-start greedy.  Returns the best cut found; best_x receives it. */
int mc_solve_multistart(const graph_t *g, int restarts, int max_passes,
                        unsigned long long seed, int *best_x) {
    const int n = g->n;
    rng_t rng; seed_rng(&rng, seed);
    int *x = (int *)malloc(sizeof(int) * (size_t)n);
    int *same = (int *)malloc(sizeof(int) * (size_t)(2 * n));
    int *other = same + n;
    int best = -1;
    for (int t = 0; t < restarts; t++) {
        for (int v = 0; v < n; v++) x[v] = (int)(next_u64(&rng) & 1ULL);
        for (int p = 0; p < max_passes; p++)
            if (!mc_pass(g, x, same, other, &rng)) break;
        const int s = mc_score(g, x);
        if (s > best) { best = s; memcpy(best_x, x, sizeof(int) * (size_t)n); }
    }
    free(x); free(same);
    return best;
}

/*
 * Multi-start with a time limit (seconds).  Used for the larger graphs where
 * the number of restarts is not known in advance.
 */
int mc_solve_timed(const graph_t *g, double time_limit, int max_passes,
                   unsigned long long seed, int *best_x) {
    const int n = g->n;
    rng_t rng; seed_rng(&rng, seed);
    int *x = (int *)malloc(sizeof(int) * (size_t)n);
    int *same = (int *)malloc(sizeof(int) * (size_t)(2 * n));
    int *other = same + n;
    int best = -1, restarts = 0;
    const double t0 = now_seconds();
    while (now_seconds() - t0 < time_limit) {
        for (int v = 0; v < n; v++) x[v] = (int)(next_u64(&rng) & 1ULL);
        for (int p = 0; p < max_passes; p++)
            if (!mc_pass(g, x, same, other, &rng)) break;
        const int s = mc_score(g, x);
        if (s > best) { best = s; memcpy(best_x, x, sizeof(int) * (size_t)n); }
        restarts++;
        if ((restarts & 31) == 0 && now_seconds() - t0 > time_limit) break;
    }
    free(x); free(same);
    return best;
}

/* ================================================================== */
/* =============================  MIS  =============================== */
/* ================================================================== */
/*
 * Andrade/Resende/Werneck style (1,2)-swap local search with iterated local
 * search ("armaru") perturbations.  in_is[v] == 1 means v belongs to the
 * independent set.
 */
typedef struct {
    const graph_t *g;
    int *in_is;
    int *free_deg;      /* #neighbours inside the IS (0 for IS vertices)   */
    int *free_list;     /* vertices outside the IS with free_deg >= 1      */
    int *pos_free;      /* position in free_list, -1 if absent             */
    int free_count;
    int is_list;        /* implicit: counted on demand                     */
    int *scratch;       /* snapshot buffer for sweeps                      */
    int *mark;          /* timestamped adjacency test                      */
    int stamp;
    long long *penalty; /* last iteration at which vertex was perturbed    */
    long long iter;
    rng_t rng;
} mis_t;

static inline void mis_free_remove(mis_t *s, int u) {
    const int p = s->pos_free[u];
    if (p < 0) return;
    const int last = --s->free_count;
    s->free_list[p] = s->free_list[last];
    s->pos_free[s->free_list[p]] = p;
    s->pos_free[u] = -1;
}

static inline void mis_free_add(mis_t *s, int u) {
    if (s->pos_free[u] >= 0 || s->in_is[u] || s->free_deg[u] <= 0) return;
    s->free_list[s->free_count] = u;
    s->pos_free[u] = s->free_count;
    s->free_count++;
}

static void mis_add(mis_t *s, int v) {
    const graph_t *g = s->g;
    s->in_is[v] = 1;
    s->free_deg[v] = 0;
    mis_free_remove(s, v);
    for (int i = g->adj_start[v]; i < g->adj_start[v + 1]; i++) {
        const int u = g->adj_flat[i];
        s->free_deg[u]++;
        mis_free_add(s, u);
    }
}

static void mis_remove(mis_t *s, int v) {
    const graph_t *g = s->g;
    s->in_is[v] = 0;
    mis_free_remove(s, v);
    for (int i = g->adj_start[v]; i < g->adj_start[v + 1]; i++) {
        const int u = g->adj_flat[i];
        if (--s->free_deg[u] == 0) mis_free_remove(s, u);
    }
}

static inline int mis_size(const mis_t *s) {
    int c = 0;
    for (int v = 0; v < s->g->n; v++) c += s->in_is[v];
    return c;
}

static inline int mis_adjacent(mis_t *s, int a, int b) {
    const graph_t *g = s->g;
    const int da = g->adj_start[a + 1] - g->adj_start[a];
    const int db = g->adj_start[b + 1] - g->adj_start[b];
    const int pivot = (da <= db) ? a : b;
    const int other = (pivot == a) ? b : a;
    const int st = ++s->stamp;
    for (int i = g->adj_start[pivot]; i < g->adj_start[pivot + 1]; i++)
        s->mark[g->adj_flat[i]] = st;
    return s->mark[other] == st;
}

/* One sweep over the free vertices applying every available (1,2) swap.
 * Returns the number of swaps performed. */
static int mis_swap_sweep(mis_t *s) {
    const graph_t *g = s->g;
    int swaps = 0;
    memcpy(s->scratch, s->free_list, sizeof(int) * (size_t)s->free_count);
    const int fc = s->free_count;
    for (int k = 0; k < fc; k++) {
        const int v = s->scratch[k];
        if (!s->in_is[v] == 0) continue;      /* v joined the IS meanwhile */
        if (s->free_deg[v] != 2) continue;
        int u = -1, w = -1;
        for (int i = g->adj_start[v]; i < g->adj_start[v + 1]; i++) {
            const int t = g->adj_flat[i];
            if (s->in_is[t]) { if (u < 0) u = t; else { w = t; break; } }
        }
        if (w < 0) continue;
        if (mis_adjacent(s, u, w)) continue;
        mis_remove(s, u);
        mis_remove(s, w);
        mis_add(s, v);
        swaps++;
    }
    return swaps;
}

/* Random-priority greedy construction of a maximal independent set. */
static void mis_construct(mis_t *s) {
    const graph_t *g = s->g;
    const int n = g->n;
    int *avail = (int *)malloc(sizeof(int) * (size_t)n);
    int *perm = (int *)malloc(sizeof(int) * (size_t)n);
    for (int i = 0; i < n; i++) { avail[i] = 1; perm[i] = i; }
    for (int i = n - 1; i > 0; i--) {
        const int j = (int)rnd_bound(&s->rng, (unsigned)(i + 1));
        const int t = perm[i]; perm[i] = perm[j]; perm[j] = t;
    }
    for (int k = 0; k < n; k++) {
        const int v = perm[k];
        if (!avail[v]) continue;
        avail[v] = 0;
        for (int i = g->adj_start[v]; i < g->adj_start[v + 1]; i++)
            avail[g->adj_flat[i]] = 0;
    }
    free(perm);
    for (int v = 0; v < n; v++) if (avail[v] == 2) mis_add(s, v);
    (void)avail;
    free(avail);
}

static void mis_reset(mis_t *s) {
    const int n = s->g->n;
    memset(s->in_is, 0, sizeof(int) * (size_t)n);
    memset(s->free_deg, 0, sizeof(int) * (size_t)n);
    memset(s->pos_free, -1, sizeof(int) * (size_t)n);
    s->free_count = 0;
}

/* Run local search to exhaustion (bounded number of sweeps). */
static void mis_local_search(mis_t *s) {
    for (int i = 0; i < 1000; i++)
        if (!mis_swap_sweep(s)) break;
}

/*
 * Full solver: `restarts` independent constructions followed by ILS under a
 * wall-clock budget.  Returns the size of the best independent set found and
 * copies it into best_is.
 */
int mis_solve(const graph_t *g, double time_limit, int max_no_improve,
              unsigned long long seed, int *best_is, int *n_restarts_out) {
    const int n = g->n;
    mis_t s;
    s.g = g;
    s.in_is = (int *)calloc(n, sizeof(int));
    s.free_deg = (int *)calloc(n, sizeof(int));
    s.free_list = (int *)malloc(sizeof(int) * (size_t)n);
    s.pos_free = (int *)malloc(sizeof(int) * (size_t)n);
    s.scratch = (int *)malloc(sizeof(int) * (size_t)n);
    s.mark = (int *)calloc(n, sizeof(int));
    s.penalty = (long long *)calloc(n, sizeof(long long));
    s.free_count = 0;
    s.stamp = 0;
    s.iter = 0;
    seed_rng(&s.rng, seed);

    int best = -1;
    int restarts = 0;
    const double t0 = now_seconds();
    int no_improve = 0;

    while (1) {
        mis_reset(&s);
        mis_construct(&s);
        mis_local_search(&s);
        int size = mis_size(&s);
        if (size > best) { best = size; memcpy(best_is, s.in_is, sizeof(int) * (size_t)n); }
        restarts++;
        /* ILS phase from the current solution */
        for (long long it = 0; it < (long long)40 * n; it++) {
            if ((it & 31) == 0 && now_seconds() - t0 >= time_limit) break;
            s.iter++;
            /* perturbation vertex: least recently perturbed among candidates */
            int v = -1;
            long long bestp = 0;
            for (int c = 0; c < 8; c++) {
                const int cand = (int)rnd_bound(&s.rng, (unsigned)n);
                if (v < 0 || s.penalty[cand] < bestp) { v = cand; bestp = s.penalty[cand]; }
            }
            s.penalty[v] = s.iter;
            if (s.in_is[v]) mis_remove(&s, v);
            for (int i = g->adj_start[v]; i < g->adj_start[v + 1]; i++)
                if (s.in_is[g->adj_flat[i]]) mis_remove(&s, g->adj_flat[i]);
            mis_local_search(&s);
            size = mis_size(&s);
            if (size > best) {
                best = size;
                memcpy(best_is, s.in_is, sizeof(int) * (size_t)n);
                no_improve = 0;
            } else {
                no_improve++;
                if (no_improve >= max_no_improve) {
                    /* restore the incumbent and continue perturbing it */
                    mis_reset(&s);
                    for (int u = 0; u < n; u++) if (best_is[u]) mis_add(&s, u);
                    no_improve = 0;
                }
            }
        }
        if (now_seconds() - t0 >= time_limit) break;
        if (restarts >= 1000000) break;
    }
    if (n_restarts_out) *n_restarts_out = restarts;
    free(s.in_is); free(s.free_deg); free(s.free_list); free(s.pos_free);
    free(s.scratch); free(s.mark); free(s.penalty);
    return best;
}

/* ===================== exported entry points ====================== */

int run_maxcut(const int *adj_start, const int *adj_flat, const int *eu,
               const int *ev, int n, int m, double time_limit, int restarts,
               int max_passes, unsigned long long seed, int *best_x) {
    graph_t g; g.n = n; g.m = m;
    g.adj_start = adj_start; g.adj_flat = adj_flat; g.eu = eu; g.ev = ev;
    if (time_limit > 0.0)
        return mc_solve_timed(&g, time_limit, max_passes, seed, best_x);
    return mc_solve_multistart(&g, restarts, max_passes, seed, best_x);
}

int run_mis(const int *adj_start, const int *adj_flat, const int *eu,
            const int *ev, int n, int m, double time_limit,
            unsigned long long seed, int *best_is, int *n_restarts) {
    graph_t g; g.n = n; g.m = m;
    g.adj_start = adj_start; g.adj_flat = adj_flat; g.eu = eu; g.ev = ev;
    return mis_solve(&g, time_limit, 1000, seed, best_is, n_restarts);
}
