/* Force every vertex of the IS to respect the invariant that its neighbours
 * were removed from consideration.  Guards against self loops / duplicate
 * edges in the input, which would otherwise corrupt the free-degree bookkeeping
 * because mis_add() only increments free_deg once per adjacency slot. */
static void mis_sanity(mis_t *s) {
    const graph_t *g = s->g;
    const int n = g->n;
    int *seen = (int *)calloc(n, sizeof(int));
    int stamp = 0;
    int *drop = (int *)malloc(sizeof(int) * (size_t)n);
    int ndrop = 0;
    memcpy(s->scratch, s->is_list, sizeof(int) * (size_t)s->is_count);
    for (int k = 0; k < s->is_count; k++) {
        const int v = s->scratch[k];
        if (!s->in_is[v]) continue;
        stamp++;
        int bad = 0;
        for (int i = g->adj_start[v]; i < g->adj_start[v + 1]; i++) {
            const int u = g->adj_flat[i];
            if (u == v) { bad = 1; break; }        /* self loop */
            if (seen[u] == stamp) { bad = 1; break; }  /* duplicate */
            seen[u] = stamp;
