387	    s.penalty = (long long *)calloc(n, sizeof(long long));
388	    s.free_count = 0;
389	    s.is_list = (int *)malloc(sizeof(int) * (size_t)n);
390	    s.pos_is = (int *)malloc(sizeof(int) * (size_t)n);
391	    s.is_count = 0;
392	    s.stamp = 0;
393	    s.iter = 0;
394	    seed_rng(&s.rng, seed);
