397	    int restarts = 0;
398	    const double t0 = now_seconds();
399	    int no_improve = 0;
400	    /* initial greedy solution becomes the incumbent */
401	    mis_reset(&s);
402	    mis_construct_masked(&s, NULL);
403	    mis_local_search(&s);
404	    best = mis_size(&s);
405	    memcpy(best_is, s.in_is, sizeof(int) * (size_t)n);
