int main(int argc, char **argv) {
    FILE *fh = fopen(argv[1], "r");
    int n, m;
    fscanf(fh, "%d %d", &n, &m);
    int *eu = malloc(sizeof(int) * m), *ev = malloc(sizeof(int) * m);
    for (int e = 0; e < m; e++) { fscanf(fh, "%d %d", &eu[e], &ev[e]); eu[e]--; ev[e]--; }
    fclose(fh);

    int *deg = calloc(n, sizeof(int));
    for (int e = 0; e < m; e++) { deg[eu[e]]++; deg[ev[e]]++; }
    int *adj_start = malloc(sizeof(int) * (n + 1));
    adj_start[0] = 0;
    for (int v = 0; v < n; v++) adj_start[v + 1] = adj_start[v] + deg[v];
    int *adj_flat = malloc(sizeof(int) * 2 * m);
    int *cur = malloc(sizeof(int) * n);
    for (int v = 0; v < n; v++) cur[v] = adj_start[v];
    for (int e = 0; e < m; e++) { adj_flat[cur[eu[e]]++] = ev[e]; adj_flat[cur[ev[e]]++] = eu[e]; }

    graph_t g = { n, m, adj_start, adj_flat, eu, ev };

    /* replicate mis_solve setup */
    mis_t s;
    s.g = &g;
    s.in_is = calloc(n, sizeof(int));
    s.free_deg = calloc(n, sizeof(int));
    s.free_list = malloc(sizeof(int) * n);
    s.pos_free = malloc(sizeof(int) * n);
    s.scratch = malloc(sizeof(int) * n);
    s.cand = malloc(sizeof(int) * n);
    s.cbuf = malloc(sizeof(int) * n);
    s.chn = calloc(n, sizeof(int));
    s.mark = calloc(n, sizeof(int));
    s.penalty = calloc(n, sizeof(long long));
    s.free_count = 0;
    s.is_list = malloc(sizeof(int) * n);
    s.pos_is = malloc(sizeof(int) * n);
    s.is_count = 0;
    s.stamp = 0; s.chn_stamp = 0; s.iter = 0;
    seed_rng(&s.rng, strtoull(argv[2], NULL, 10));

    mis_reset(&s);
    printf("after reset        : %d\n", mis_size(&s));
    mis_construct_masked(&s, NULL);
    printf("after construct    : %d (free=%d)\n", mis_size(&s), s.free_count);
    /* verify independence */
    int bad = 0;
    for (int v = 0; v < n; v++) if (s.in_is[v])
        for (int i = adj_start[v]; i < adj_start[v + 1]; i++) if (s.in_is[adj_flat[i]]) bad++;
    printf("conflict edges     : %d\n", bad / 2);
    int sw = mis_local_search(&s), dummy = (void)sw - sw; (void)dummy;
