/*
 * One (1,2)-swap pass in the sense of Andrade/Resende/Werneck (2012).
 *
 * A vertex v outside the set with exactly one neighbour u inside it is a swap
 * centre: removing u frees v and every other neighbour of u that was blocked
 * only by u, and re-adding two of those neighbours grows the set by one.
 * Each vertex participates in at most one swap per pass.  Returns the net
 * change in set size (never negative).
 */
static int mis_swap_sweep(mis_t *s) {
    const graph_t *g = s->g;
    const int fc = s->free_count;
    memcpy(s->cand, s->free_list, sizeof(int) * (size_t)fc);
    s->chn_stamp++;
    int delta = 0;
    for (int k = 0; k < fc; k++) {
        const int v = s->cand[k];
        if (s->in_is[v]) continue;              /* v joined the set meanwhile  */
        if (s->free_deg[v] != 1) continue;      /* not a swap centre           */
        if (mis_touched(s, v)) continue;        /* already re-optimised        */
        int u = -1;
        for (int i = g->adj_start[v]; i < g->adj_start[v + 1]; i++)
            if (s->in_is[g->adj_flat[i]]) { u = g->adj_flat[i]; break; }
        if (u < 0 || mis_touched(s, u)) continue;
        /* neighbours of u that are blocked by u alone (swap partners) */
        int nc = 0;
        for (int i = g->adj_start[u]; i < g->adj_start[u + 1]; i++) {
            const int t = g->adj_flat[i];
            if (s->in_is[t] || s->free_deg[t] != 1) continue;
            if (mis_touched(s, t)) continue;
            s->cbuf[nc++] = t;
        }
