 * One 2-improvement pass in the sense of Andrade/Resende/Werneck (2012).
 *
 * A vertex v outside the independent set with exactly two IS neighbours u, w
 * is a swap centre: removing u and w and inserting v keeps the set independent
 * (u and w must not be adjacent) and gains one vertex.  Every centre is used at
 * most once per pass; vertices already touched by an earlier swap in the same
 * pass are skipped so the pass stays linear and monotone.  Returns the number
 * of swaps performed.
 */
static int mis_swap_sweep(mis_t *s) {
    const graph_t *g = s->g;
    int swaps = 0;
    const int fc = s->free_count;
    memcpy(s->cand, s->free_list, sizeof(int) * (size_t)fc);
    s->chn_stamp++;
    for (int k = 0; k < fc; k++) {
        const int v = s->cand[k];
        if (s->in_is[v]) continue;              /* v joined the IS meanwhile  */
        if (s->free_deg[v] != 2) continue;      /* not a swap centre          */
        if (mis_touched(s, v)) continue;        /* already re-optimised       */
        int nb = 0;
        for (int i = g->adj_start[v]; i < g->adj_start[v + 1]; i++) {
            const int t = g->adj_flat[i];
            if (s->in_is[t]) s->cbuf[nb++] = t;
        }
        if (nb < 2) continue;
        int done = 0;
        for (int i = 0; i < nb && !done; i++) {
            for (int j = i + 1; j < nb && !done; j++) {
                const int u = s->cbuf[i], w = s->cbuf[j];
                if (mis_adjacent(s, u, w)) continue;   /* swap would conflict */
                mis_remove(s, u);
                mis_remove(s, w);
                mis_add(s, v);
                mis_touch(s, v); mis_touch(s, u); mis_touch(s, w);
                swaps++;
                done = 1;
            }
        }
    }
    return swaps;
