import os
import sys
import random

import numpy as np

sys.path.insert(0, "/workspace/src")
import graph_utils as gu


def ls_maxcut(g, x, rnd, max_passes=200):
    x = x.copy()
    nbrs = [g.adj_flat[g.adj_start[v]:g.adj_start[v + 1]] for v in range(g.n)]
    for _ in range(max_passes):
        moved = 0
        order = list(range(g.n))
        rnd.shuffle(order)
        for v in order:
            same = sum(1 for u in nbrs[v] if x[u] == x[v])
            other = len(nbrs[v]) - same
            if (x[v] == 0 and other >= same) or (x[v] == 1 and same >= other):
                continue
            x[v] ^= 1
            moved += 1
        if moved == 0:
            break
    return int(np.count_nonzero(x[g.edges_u] != x[g.edges_v]))


