    if rnd:
        rnd.shuffle(roots)
    for st in roots:
        if color[st] >= 0:
            continue
        color[st] = rnd.randint(0, 1) if rnd else 0
        q = deque([st])
        while q:
            v = q.popleft()
            for i in range(g.adj_start[v], g.adj_start[v + 1]):
                u = int(g.adj_flat[i])
                if color[u] < 0:
                    color[u] = 1 - color[v]
                    q.append(u)
    return color


