82	static int mc_pass(const graph_t *g, int *x, int *same, int *other, rng_t *rng) {
83	    const int n = g->n, m = g->m;
84	    for (int v = 0; v < n; v++) { same[v] = 0; other[v] = 0; }
85	    for (int e = 0; e < m; e++) {
86	        const int u = g->eu[e], v = g->ev[e];
87	        if (x[u] == x[v]) { same[u]++; same[v]++; }
88	        else              { other[u]++; other[v]++; }
89	    }
90	    int *order = (int *)malloc(sizeof(int) * (size_t)n);
91	    for (int i = 0; i < n; i++) order[i] = i;
92	    for (int i = n - 1; i > 0; i--) {
93	        int j = (int)rnd_bound(rng, (unsigned)(i + 1));
94	        int t = order[i]; order[i] = order[j]; order[j] = t;
95	    }
96	    int moved = 0;
97	    for (int k = 0; k < n; k++) {
98	        const int v = order[k];
99	        if (x[v] == 0) {
100	            if (other[v] >= same[v]) continue;
101	            x[v] = 1; moved++;
102	        } else {
103	            if (same[v] >= other[v]) continue;
104	            x[v] = 0; moved++;
105	        }
106	        const int s = g->adj_start[v], e = g->adj_start[v + 1];
107	        for (int i = s; i < e; i++) {
108	            const int u = g->adj_flat[i];
109	            if (x[u] == x[v]) { same[u]++; other[u]--; }
110	            else              { same[u]--; other[u]++; }
111	        }
112	    }
113	    free(order);
114	    return moved;
