318	    s->chn_stamp++;
319	    int delta = 0;
320	    for (int k = 0; k < fc; k++) {
321	        const int v = s->cand[k];
322	        if (s->in_is[v]) continue;              /* v joined the set meanwhile  */
323	        if (s->free_deg[v] != 1) continue;      /* not a swap centre           */
