{"arguments":{"file_path":"/workspace/src/ccores.c","new_string":"/* One greedy descent pass restricted to vertices whose flip is improving.
 * Used to polish the output of the annealing stage. */
static void mc_descend(const graph_t *g, int *x, int *same, int *other, rng_t *rng) {
    const int n = g->n;
    int *stack = (int *)malloc(sizeof(int) * (size_t)n);
    int changed = 1;
    while (changed) {
        changed = 0;
        int top = 0;
        for (int v = 0; v < n; v++)
            if (same[v] > other[v]) stack[top++] = v;
        for (int i = top - 1; i > 0; i--) {
            int j = (int)rnd_bound(rng, (unsigned)(i + 1));
            int t = stack[i]; stack[i] = stack[j]; stack[j] = t;
        }
        for (int k = 0; k < top; k++) {
            const int v = stack[k];
            if (same[v] <= other[v]) continue;
            x[v] ^= 1;
            changed = 1;
            for (int i = g->adj_start[v]; i < g->adj_start[v + 1]; i++) {
                const int u = g->adj_flat[i];
                if (x[u] == x[v]) { same[u]++; other[u]--; }
                else              { same[u]--; other[u]++; }
            }
        }
    }
    free(stack);
}

/* Recompute the same/other neighbour counts of every vertex from scratch. */
static void mc_counts(const graph_t *g, const int *x, int *same, int *other) {
    const int n = g->n;
    for (int v = 0; v < n; v++) { same[v] = 0; other[v] = 0; }
    for (int e = 0; e < g->m; e++) {
        const int u = g->eu[e], v = g->ev[e];
        if (x[u] == x[v]) { same[u]++; same[v]++; }
        else              { other[u]++; other[v]++; }
    }
}

/*
 * Simulated annealing over single-vertex flips with periodic reheating,
 * polished by a greedy descent whenever a new incumbent appears.  The flip of
 * vertex v changes the cut by (other[v] - same[v]), so the neighbour counts
 * give the exact delta in O(1); updating them costs O(deg(v)).
 */
int mc_solve_timed(const graph_t *g, double time_limit, int max_passes,
                   unsigned long long seed, int *best_x) {
    const int n = g->n;
    rng_t rng; seed_rng(&rng, seed);
    int *x = (int *)malloc(sizeof(int) * (size_t)n);
    int *same = (int *)malloc(sizeof(int) * (size_t)(2 * n));
    int *other = same + n;
    int best;
    const double t0 = now_seconds();

    /* initial random solution + greedy descent */
    for (int v = 0; v < n; v++) x[v] = (int)(next_u64(&rng) & 1ULL);
    mc_counts(g, x, same, other);
    mc_descend(g, x, same, other, &rng);
    best = mc_score(g, x);
    memcpy(best_x, x, sizeof(int) * (size_t)n);

    /* temperature is scaled by the average degree so that the schedule
     * transfers between sparse and dense graphs */
    double avg_deg = 2.0 * (double)g->m / (double)n;
    double T = 0.35 * avg_deg;
    const double T_min = 0.02, T_cool = 0.999999;
    long long steps = 0;
    while (now_seconds() - t0 < time_limit) {
        const int v = (int)rnd_bound(&rng, (unsigned)n);
        const int delta = other[v] - same[v];       /* cut change if flipped */
        if (delta >= 0 || rnd_double(&rng) < exp((double)delta / T)) {
            x[v] ^= 1;
            for (int i = g->adj_start[v]; i < g->adj_start[v + 1]; i++) {
                const int u = g->adj_flat[i];
                if (x[u] == x[v]) { same[u]++; other[u]--; }
                else              { same[u]--; other[u]++; }
            }
            if (delta < 0) {
                /* only re-score after a worsening flip; improving flips are
                 * accounted for by the delta itself */
            }
        }
        if ((++steps & 1023) == 0) {
            T *= T_cool;
            if (T < T_min) T = T_min;
            const int s = mc_score(g, x);
            if (s > best) {
                best = s;
                memcpy(best_x, x, sizeof(int) * (size_t)n);
                mc_descend(g, x, same, other, &rng);   /* polish the incumbent */
                if (mc_score(g, x) >= best) {
                    best = mc_score(g, x);
                    memcpy(best_x, x, sizeof(int) * (size_t)n);
                }
                T = 0.15 * avg_deg;                     /* reheat */
            }
        }
    }
    /* final polish from the incumbent */
    memcpy(x, best_x, sizeof(int) * (size_t)n);
    mc_counts(g, x, same, other);
    mc_descend(g, x, same, other, &rng);
    const int s = mc_score(g, x);
    if (s > best) { best = s; memcpy(best_x, x, sizeof(int) * (size_t)n); }
    free(x); free(same);
    (void)max_passes;
    return best;
