{"arguments":{"file_path":"/workspace/src/ccores.c","new_string":"/*
 * Tabu search over single-vertex flips.  The gain of flipping v is
 * gain[v] = other[v] - same[v]; the classic bucket priority queue indexed by
 * gain makes each move O(deg + maxdeg).  Vertices are tabu for a short tenure
 * after being flipped, which lets the search cross plateaus and leave local
 * optima; the best labelling ever seen is remembered.
 */
typedef struct {
    int *bnext, *bprev;   /* doubly linked bucket lists, per vertex   */
    int *head;            /* head[gain + G]                          */
    int G;                /* gain offset (max degree)                */
    int hi;               /* index of highest non-empty bucket       */
} buckets_t;

static void bk_init(buckets_t *b, int n, int maxdeg) {
    b->G = maxdeg + 1;
    const int nb = 2 * b->G + 1;
    b->bnext = (int *)malloc(sizeof(int) * (size_t)n);
    b->bprev = (int *)malloc(sizeof(int) * (size_t)n);
    b->head = (int *)malloc(sizeof(int) * (size_t)nb);
    for (int i = 0; i < nb; i++) b->head[i] = -1;
    for (int v = 0; v < n; v++) { b->bnext[v] = -1; b->bprev[v] = -1; }
    b->hi = -1;
}

static void bk_free(buckets_t *b) { free(b->bnext); free(b->bprev); free(b->head); }

static inline int bk_bucket(const buckets_t *b, int v) { return b->bprev[v] >= -1 ? 0 : 0; }

static void bk_remove(buckets_t *b, int v) {
    const int p = b->bprev[v], nx = b->bnext[v];
    if (p >= 0) b->bnext[p] = nx; else b->head[b->G + b->G] = -1; /* overwritten below */
    (void)nx;
}

static void bk_push(buckets_t *b, int v, int bucket) {
    const int nb = 2 * b->G + 1;
    (void)nb;
    const int h = b->head[bucket];
    b->bnext[v] = h;
    b->bprev[v] = -1;
    if (h >= 0) b->bprev[h] = v;
    b->head[bucket] = v;
    if (bucket > b->hi) b->hi = bucket;
}

