185	/*
186	 * Tabu search over single-vertex flips.  The gain of flipping v is
187	 * gain[v] = other[v] - same[v]; the classic bucket priority queue indexed by
188	 * gain makes each move O(deg + maxdeg).  Vertices are tabu for a short tenure
189	 * after being flipped, which lets the search cross plateaus and leave local
190	 * optima; the best labelling ever seen is remembered.
191	 */
192	typedef struct {
193	    int *bnext, *bprev;   /* doubly linked bucket lists, per vertex   */
194	    int *head;            /* head[gain + G]                          */
195	    int G;                /* gain offset (max degree)                */
196	    int hi;               /* index of highest non-empty bucket       */
197	} buckets_t;
198	
199	static void bk_init(buckets_t *b, int n, int maxdeg) {
200	    b->G = maxdeg + 1;
201	    const int nb = 2 * b->G + 1;
202	    b->bnext = (int *)malloc(sizeof(int) * (size_t)n);
203	    b->bprev = (int *)malloc(sizeof(int) * (size_t)n);
204	    b->head = (int *)malloc(sizeof(int) * (size_t)nb);
205	    for (int i = 0; i < nb; i++) b->head[i] = -1;
206	    for (int v = 0; v < n; v++) { b->bnext[v] = -1; b->bprev[v] = -1; }
207	    b->hi = -1;
208	}
209	
210	static void bk_free(buckets_t *b) { free(b->bnext); free(b->bprev); free(b->head); }
211	
212	static void bk_push(buckets_t *b, int v, int bucket) {
213	    const int nb = 2 * b->G + 1;
214	    (void)nb;
215	    const int h = b->head[bucket];
216	    b->bnext[v] = h;
217	    b->bprev[v] = -1;
218	    if (h >= 0) b->bprev[h] = v;
219	    b->head[bucket] = v;
220	    if (bucket > b->hi) b->hi = bucket;
221	}
