188	/*
189	 * Tabu search over single-vertex flips.  The gain of flipping v is
190	 * gain[v] = other[v] - same[v]; the classic bucket priority queue indexed by
191	 * gain makes each move O(deg + maxdeg).  Vertices are tabu for a short tenure
192	 * after being flipped, which lets the search cross plateaus and leave local
193	 * optima; the best labelling ever seen is remembered.
194	 */
195	typedef struct {
196	    int *bnext, *bprev;   /* doubly linked bucket lists, per vertex   */
197	    int *head;            /* head[gain + G]                          */
198	    int G;                /* gain offset (max degree)                */
199	    int hi;               /* index of highest non-empty bucket       */
200	} buckets_t;
201	
202	static void bk_init(buckets_t *b, int n, int maxdeg) {
203	    b->G = maxdeg + 1;
204	    const int nb = 2 * b->G + 1;
205	    b->bnext = (int *)malloc(sizeof(int) * (size_t)n);
206	    b->bprev = (int *)malloc(sizeof(int) * (size_t)n);
207	    b->head = (int *)malloc(sizeof(int) * (size_t)nb);
208	    for (int i = 0; i < nb; i++) b->head[i] = -1;
209	    for (int v = 0; v < n; v++) { b->bnext[v] = -1; b->bprev[v] = -1; }
210	    b->hi = -1;
211	}
212	
213	static void bk_free(buckets_t *b) { free(b->bnext); free(b->bprev); free(b->head); }
