215	static void bk_push(buckets_t *b, int v, int bucket) {
216	    const int nb = 2 * b->G + 1;
217	    (void)nb;
218	    const int h = b->head[bucket];
219	    b->bnext[v] = h;
220	    b->bprev[v] = -1;
221	    if (h >= 0) b->bprev[h] = v;
222	    b->head[bucket] = v;
223	    if (bucket > b->hi) b->hi = bucket;
