 * Anytime MaxCut driver.  Each round starts from a fresh random labelling,
 * descends greedily, then runs tabu search for the remaining slice of the
 * budget; the best labelling over all rounds is returned.  Multiple rounds
 * both diversify the search and hedge against an unlucky first descent, which
 * alone can vary by several percent in cut value.
 */
int mc_solve_timed(const graph_t *g, double time_limit, int max_passes,
                   unsigned long long seed, int *best_x) {
    const int n = g->n;
    rng_t rng; seed_rng(&rng, seed);
    int *x = (int *)malloc(sizeof(int) * (size_t)n);
    int *same = (int *)malloc(sizeof(int) * (size_t)(2 * n));
    int *other = same + n;
    const double t0 = now_seconds();
    const double deadline = t0 + time_limit;
    int best = -1;
    int round = 0;
    while (now_seconds() < deadline) {
        round++;
        /* leave a little room for a final polish round */
        const double left = deadline - now_seconds();
        const double slice = (round == 1) ? left * 0.5 : left * 0.4;
        for (int v = 0; v < n; v++) x[v] = (int)(next_u64(&rng) & 1ULL);
        mc_counts(g, x, same, other);
        mc_descend(g, x, same, other, &rng);
        int *round_x = (int *)malloc(sizeof(int) * (size_t)n);
        const int s = mc_tabu(g, x, same, other, slice, &rng, round_x);
        if (s > best) { best = s; memcpy(best_x, round_x, sizeof(int) * (size_t)n); }
