/*
 * Greedy fill: add every vertex that currently has no neighbour in the set.
 * Keeps the independent set maximal, which is a precondition for the
 * (1,2)-swap pass below and repairs the damage left by a perturbation.
 * Returns the number of vertices added.
 */
static int mis_fill(mis_t *s) {
    const graph_t *g = s->g;
    int added = 0;
    int nc = 0;
    for (int v = 0; v < g->n; v++)
        if (!s->in_is[v] && s->free_deg[v] == 0) s->cand[nc++] = v;
    for (int i = nc - 1; i > 0; i--) {
        const int j = (int)rnd_bound(&s->rng, (unsigned)(i + 1));
        const int t = s->cand[i]; s->cand[i] = s->cand[j]; s->cand[j] = t;
    }
    for (int k = 0; k < nc; k++) {
        const int v = s->cand[k];
        if (s->in_is[v] || s->free_deg[v] != 0) continue;
        mis_add(s, v);
        added++;
    }
    return added;
}

/*
