/*
 * Multi-start with a time limit (seconds).  Each round perturbs the incumbent
 * by flipping a small random set of vertices and re-optimises it with greedy
 * passes (basin hopping), which explores the neighbourhood of a good cut far
 * more efficiently than restarting from a random labelling.
 */
int mc_solve_timed(const graph_t *g, double time_limit, int max_passes,
                   unsigned long long seed, int *best_x) {
