/*
 * Anytime MaxCut driver: random start, greedy descent, then tabu search for
 * the remaining budget.  Basin hopping around the incumbent proved weaker
 * than tabu on every instance family, so tabu is the only second stage.
 */
int mc_solve_timed(const graph_t *g, double time_limit, int max_passes,
                   unsigned long long seed, int *best_x) {
    const int n = g->n;
    rng_t rng; seed_rng(&rng, seed);
    int *x = (int *)malloc(sizeof(int) * (size_t)n);
    int *same = (int *)malloc(sizeof(int) * (size_t)(2 * n));
    int *other = same + n;
    const double t0 = now_seconds();
    for (int v = 0; v < n; v++) x[v] = (int)(next_u64(&rng) & 1ULL);
    mc_counts(g, x, same, other);
    mc_descend(g, x, same, other, &rng);
    const int best = mc_tabu(g, x, same, other, time_limit - (now_seconds() - t0),
                             &rng, best_x);
    free(x); free(same);
    (void)max_passes;
    return best;
}

