 * One (2,3)-swap pass: the natural extension of the (1,2)-swap to centres
 * with two neighbours inside the set.  Removing both blockers u1, u2 frees
 * the centre v and every vertex that was blocked by u1 or u2 alone, so up to
 * three vertices can be re-added for a net gain of one.  Swaps that break
 * even (two added for two removed) are accepted as plateau moves: they
 * re-shuffle the set without shrinking it and are what eventually uncovers
 * further (1,2)-swaps on random regular graphs, where plain (1,2)-swaps
 * stall well short of the true independence number.
 */
static int mis_swap23_sweep(mis_t *s) {
    const graph_t *g = s->g;
    const int fc = s->free_count;
    memcpy(s->cand, s->free_list, sizeof(int) * (size_t)fc);
    s->chn_stamp++;
    int delta = 0;
    for (int k = 0; k < fc; k++) {
        const int v = s->cand[k];
        if (s->in_is[v]) continue;
        if (s->free_deg[v] != 2) continue;      /* not a (2,3) centre        */
        if (mis_touched(s, v)) continue;
        /* the two blockers of v */
        int u1 = -1, u2 = -1;
        for (int i = g->adj_start[v]; i < g->adj_start[v + 1]; i++) {
            const int t = g->adj_flat[i];
            if (!s->in_is[t]) continue;
            if (u1 < 0) u1 = t;
            else if (u2 < 0) { u2 = t; break; }
        }
        if (u2 < 0 || mis_touched(s, u1) || mis_touched(s, u2)) continue;
        /* vertices that become addable once u1 and u2 leave: the neighbours
         * of either blocker that are blocked by that blocker alone */
        int nc = 0;
        for (int i = g->adj_start[u1]; i < g->adj_start[u1 + 1]; i++) {
            const int t = g->adj_flat[i];
            if (s->in_is[t] || s->free_deg[t] != 1) continue;
            if (mis_touched(s, t)) continue;
            s->cbuf[nc++] = t;
        }
        for (int i = g->adj_start[u2]; i < g->adj_start[u2 + 1]; i++) {
            const int t = g->adj_flat[i];
            if (s->in_is[t] || s->free_deg[t] != 1) continue;
            if (mis_touched(s, t)) continue;
            s->cbuf[nc++] = t;
        }
        if (nc < 2) continue;                   /* cannot even break even    */
        for (int i = nc - 1; i > 0; i--) {
            const int j = (int)rnd_bound(&s->rng, (unsigned)(i + 1));
            const int t = s->cbuf[i]; s->cbuf[i] = s->cbuf[j]; s->cbuf[j] = t;
        }
        mis_remove(s, u1);
        mis_touch(s, u1);
        mis_remove(s, u2);
        mis_touch(s, u2);
        int added = 0;
        if (!s->in_is[v] && s->free_deg[v] == 0) {
            mis_add(s, v);
            mis_touch(s, v);
            added++;
        }
        for (int i = 0; i < nc && added < 3; i++) {
            const int t = s->cbuf[i];
            if (s->in_is[t] || s->free_deg[t] != 0 || mis_touched(s, t)) continue;
            mis_add(s, t);
            mis_touch(s, t);
            added++;
        }
        delta += added - 2;                     /* >= 0 by the nc >= 2 test  */
    }
    return delta;
}

