760	    s.mark = (int *)calloc(n, sizeof(int));
761	    s.penalty = (long long *)calloc(n, sizeof(long long));
762	    s.free_count = 0;
763	    s.is_list = (int *)malloc(sizeof(int) * (size_t)n);
764	    s.pos_is = (int *)malloc(sizeof(int) * (size_t)n);
765	    s.is_count = 0;
