534	/*
535	 * One (1,2)-swap pass in the sense of Andrade/Resende/Werneck (2012).
536	 *
537	 * A vertex v outside the set with exactly one neighbour u inside it is a swap
538	 * centre: removing u frees v and every other neighbour of u that was blocked
539	 * only by u, and re-adding two of those neighbours grows the set by one.
540	 * Each vertex participates in at most one swap per pass.  Returns the net
541	 * change in set size (never negative).
542	 */
543	static int mis_swap_sweep(mis_t *s) {
544	    const graph_t *g = s->g;
545	    const int fc = s->free_count;
546	    memcpy(s->cand, s->free_list, sizeof(int) * (size_t)fc);
547	    s->chn_stamp++;
548	    int delta = 0;
549	    for (int k = 0; k < fc; k++) {
550	        const int v = s->cand[k];
551	        if (s->in_is[v]) continue;              /* v joined the set meanwhile  */
552	        if (s->free_deg[v] != 1) continue;      /* not a swap centre           */
553	        if (mis_touched(s, v)) continue;        /* already re-optimised        */
554	        int u = -1;
555	        for (int i = g->adj_start[v]; i < g->adj_start[v + 1]; i++)
556	            if (s->in_is[g->adj_flat[i]]) { u = g->adj_flat[i]; break; }
557	        if (u < 0 || mis_touched(s, u)) continue;
558	        /* neighbours of u that are blocked by u alone (swap partners) */
559	        int nc = 0;
560	        for (int i = g->adj_start[u]; i < g->adj_start[u + 1]; i++) {
561	            const int t = g->adj_flat[i];
562	            if (s->in_is[t] || s->free_deg[t] != 1) continue;
563	            if (mis_touched(s, t)) continue;
564	            s->cbuf[nc++] = t;
565	        }
566	        if (nc < 2) continue;                   /* no improving swap here      */
567	        for (int i = nc - 1; i > 0; i--) {
568	            const int j = (int)rnd_bound(&s->rng, (unsigned)(i + 1));
569	            const int t = s->cbuf[i]; s->cbuf[i] = s->cbuf[j]; s->cbuf[j] = t;
570	        }
571	        mis_remove(s, u);
572	        mis_touch(s, u);
573	        int added = 0;
574	        for (int i = 0; i < nc && added < 2; i++) {
575	            const int t = s->cbuf[i];
576	            if (s->in_is[t] || s->free_deg[t] != 0) continue;
577	            mis_add(s, t);
578	            mis_touch(s, t);
579	            added++;
580	        }
581	        delta += added - 1;                     /* added >= 1 because v is free */
582	    }
583	    return delta;
584	}
585	
586	/*
587	 * One (2,3)-swap pass: the natural extension of the (1,2)-swap to centres
588	 * with two neighbours inside the set.  Removing both blockers u1, u2 frees
589	 * the centre v and every vertex that was blocked by u1 or u2 alone, so up to
590	 * three vertices can be re-added for a net gain of one.  Swaps that break
591	 * even (two added for two removed) are accepted as plateau moves: they
592	 * re-shuffle the set without shrinking it and are what eventually uncovers
593	 * further (1,2)-swaps on random regular graphs, where plain (1,2)-swaps
594	 * stall well short of the true independence number.
595	 */
596	static int mis_swap23_sweep(mis_t *s) {
597	    const graph_t *g = s->g;
598	    const int fc = s->free_count;
599	    memcpy(s->cand, s->free_list, sizeof(int) * (size_t)fc);
600	    s->chn_stamp++;
601	    int delta = 0;
602	    for (int k = 0; k < fc; k++) {
603	        const int v = s->cand[k];
604	        if (s->in_is[v]) continue;
605	        if (s->free_deg[v] != 2) continue;      /* not a (2,3) centre        */
606	        if (mis_touched(s, v)) continue;
607	        /* the two blockers of v */
608	        int u1 = -1, u2 = -1;
609	        for (int i = g->adj_start[v]; i < g->adj_start[v + 1]; i++) {
610	            const int t = g->adj_flat[i];
611	            if (!s->in_is[t]) continue;
612	            if (u1 < 0) u1 = t;
613	            else if (u2 < 0) { u2 = t; break; }
614	        }
615	        if (u2 < 0 || mis_touched(s, u1) || mis_touched(s, u2)) continue;
616	        /* vertices that become addable once u1 and u2 leave: the neighbours
617	         * of either blocker that are blocked by that blocker alone */
618	        int nc = 0;
619	        for (int i = g->adj_start[u1]; i < g->adj_start[u1 + 1]; i++) {
620	            const int t = g->adj_flat[i];
621	            if (s->in_is[t] || s->free_deg[t] != 1) continue;
622	            if (mis_touched(s, t)) continue;
623	            s->cbuf[nc++] = t;
624	        }
625	        for (int i = g->adj_start[u2]; i < g->adj_start[u2 + 1]; i++) {
626	            const int t = g->adj_flat[i];
627	            if (s->in_is[t] || s->free_deg[t] != 1) continue;
628	            if (mis_touched(s, t)) continue;
629	            s->cbuf[nc++] = t;
630	        }
631	        if (nc < 2) continue;                   /* cannot even break even    */
632	        for (int i = nc - 1; i > 0; i--) {
633	            const int j = (int)rnd_bound(&s->rng, (unsigned)(i + 1));
634	            const int t = s->cbuf[i]; s->cbuf[i] = s->cbuf[j]; s->cbuf[j] = t;
635	        }
636	        mis_remove(s, u1);
637	        mis_touch(s, u1);
638	        mis_remove(s, u2);
639	        mis_touch(s, u2);
640	        int added = 0;
641	        if (!s->in_is[v] && s->free_deg[v] == 0) {
642	            mis_add(s, v);
643	            mis_touch(s, v);
644	            added++;
645	        }
646	        for (int i = 0; i < nc && added < 3; i++) {
647	            const int t = s->cbuf[i];
648	            if (s->in_is[t] || s->free_deg[t] != 0 || mis_touched(s, t)) continue;
649	            mis_add(s, t);
650	            mis_touch(s, t);
651	            added++;
652	        }
653	        delta += added - 2;                     /* >= 0 by the nc >= 2 test  */
654	    }
655	    return delta;
