360	 * Anytime MaxCut driver: iterated tabu search.  See mc_solve_timed below.
361	/*
362	 * Anytime MaxCut driver: iterated tabu search.  Every round starts from a
363	 * copy of the incumbent perturbed by a burst of random flips (round 1 starts
364	 * from a uniformly random labelling), then hands over to tabu search for a
365	 * slice of the remaining budget.  The perturbation provides the
366	 * diversification that plain tabu search lacks on geometric instances, while
367	 * the tabu stage supplies the intensification that a single greedy descent
368	 * lacks; keeping the incumbent as the base makes this a basin-hopping search
369	 * whose local search is tabu rather than greedy.
370	 */
371	int mc_solve_timed(const graph_t *g, double time_limit, int max_passes,
372	                   unsigned long long seed, int *best_x) {
373	    const int n = g->n;
374	    rng_t rng; seed_rng(&rng, seed);
375	    int *x = (int *)malloc(sizeof(int) * (size_t)n);
376	    int *round_x = (int *)malloc(sizeof(int) * (size_t)n);
377	    int *same = (int *)malloc(sizeof(int) * (size_t)(2 * n));
378	    int *other = same + n;
379	    const double deadline = now_seconds() + time_limit;
380	    int best = -1;
381	    int round = 0;
382	    while (now_seconds() < deadline) {
383	        round++;
384	        /* half of what is left, so the rounds decay geometrically and the
385	         * search never commits the whole budget to a single basin */
386	        const double slice = (deadline - now_seconds()) * 0.5;
387	        if (round == 1 || best < 0) {
388	            for (int v = 0; v < n; v++) x[v] = (int)(next_u64(&rng) & 1ULL);
389	        } else {
390	            memcpy(x, best_x, sizeof(int) * (size_t)n);
391	            /* perturbation strength drawn at random, from a single flip up to
392	             * ~5% of the vertices, so small and large kicks both occur */
393	            const int kmax = n / 20 + 1;
394	            const int k = 1 + (int)rnd_bound(&rng, (unsigned)kmax);
395	            for (int i = 0; i < k; i++)
396	                x[(int)rnd_bound(&rng, (unsigned)n)] ^= 1;
397	        }
398	        mc_counts(g, x, same, other);
399	        mc_descend(g, x, same, other, &rng);
400	        const int s = mc_tabu(g, x, same, other, slice, &rng, round_x);
401	        if (s > best) { best = s; memcpy(best_x, round_x, sizeof(int) * (size_t)n); }
402	        if (slice <= 0.0) break;
403	    }
404	    free(x); free(round_x); free(same);
405	    (void)max_passes;
406	    return best;
407	}
