{"arguments":{"content":""""Data loading and preprocessing utilities for microbiome -> metabolome prediction."""
import os
import numpy as np
import pandas as pd


def load_instance(data_dir, instance):
    """Load one instance's raw tables.

    Returns dict with:
      X_train (DataFrame taxa x samples), Y_train (metabolites x samples),
      X_test  (taxa x test samples)
    """
    d = os.path.join(data_dir, instance)
    if instance == "ibd":
        X_train = pd.read_csv(os.path.join(d, "microbiome_PRISM.csv"), index_col=0)
        Y_train = pd.read_csv(os.path.join(d, "metabolome_PRISM.csv"), index_col=0)
        X_test = pd.read_csv(os.path.join(d, "microbiome_external.csv"), index_col=0)
        ann = pd.read_csv(os.path.join(d, "metabolome_annotation.csv"), index_col=0)
        diag = pd.read_csv(os.path.join(d, "diagnosis_PRISM.csv"), index_col=0)
    else:
        X_train = pd.read_csv(os.path.join(d, "microbiome_train.csv"), index_col=0)
        Y_train = pd.read_csv(os.path.join(d, "metabolome_train.csv"), index_col=0)
        X_test = pd.read_csv(os.path.join(d, "microbiome_test.csv"), index_col=0)
        ann, diag = None, None

    # align samples by ID
    common = [c for c in X_train.columns if c in set(Y_train.columns)]
    Y_train = Y_train[common]
    X_train = X_train[common]
    # align taxa between train and test
    taxa = [t for t in X_train.index if t in set(X_test.index)]
    X_train = X_train.loc[taxa]
    X_test = X_test.loc[taxa]
    return dict(X_train=X_train, Y_train=Y_train, X_test=X_test,
                annotation=ann, diagnosis=diag)


# ---------------- preprocessing transforms ----------------

def transform_microbiome(X_df, mode="clr"):
    """X_df: taxa x samples -> returns features x samples array."""
    A = X_df.values.astype(np.float64)
    if mode == "raw":
        F = A.T.copy()                      # samples x taxa
    elif mode == "log":
        F = np.log1p(A.T * 1e4)             # counts-scale then log
    elif mode == "clr":
        A = A / A.sum(axis=0, keepdims=True)
        A = np.clip(A, 0, None)
        z = np.log(A + 1e-4)
        F = z - z.mean(axis=1, keepdims=True)
    elif mode == "lognorm":
        A = A / np.maximum(A.sum(axis=0, keepdims=True), 1e-12)
        F = np.log1p(A.T * 1e4)
    else:
        raise ValueError(mode)
    return F


def transform_metabolome_in(Y_df, kind="log"):
    """Y: metabolites x samples -> samples x metabolites (transformed)."""
    Y = Y_df.values.astype(np.float64).T
    if kind == "log":
        return np.log1p(Y)
    elif kind == "raw":
        return Y.copy()
    elif kind == "sqrt":
        return np.sqrt(Y)
    raise ValueError(kind)


def transform_metabolome_out(P, kind="log"):
    """Inverse transform predictions back to concentration scale."""
    if kind == "log":
        return np.expm1(P)
    elif kind == "raw":
        return P
    elif kind == "sqrt":
        return np.clip(P, 0, None) ** 2
    raise ValueError(kind)
