{"arguments":{"content":""""Hypergraph -> graph reduction utilities.

A hyperedge e is *cut* iff not all of its nodes share one label.  Writing
c(S) = product_{i in e} x_i  (x in {-1,+1}) we have

    cut(e) = (1 - c(S)) / 2                         (plain count)
    cut_w(e) = sum_{S subset |S|>=2} (2^{|e|-|S|-1} - c(e)+c(S)) / 2

so the *plain* objective is linear in the pair indicators y_ij = (1-x_i x_j)/2:

    plain:   max  sum_e [ e_1 == 0 ] * y_{e1 e2}  ... (exact, low weight)
    weighted: max  sum_e sum_{i<j in e} 2^{|e|-2} y_ij  (weights, exact)

`weighted` uses huge weights (2^|e|-1 per pair) but is pairwise-linear and
drives local search well because a hyperedge stops contributing only when it
becomes monochromatic; intermediate colour mixes still earn partial credit so
the search landscape is smoother.  We optimise the weighted proxy and always
report true cut values computed exactly.
"""
import numpy as np


def pair_decomposition(edges, n, weighted):
    """Return (ei, ej, w) pairwise decomposition of the hypergraph."""
    E, J, W = [], [], []
    if weighted:
        cache = {}
        for e in edges:
            k = len(e)
            if k < 2:
                continue
            if k not in cache:
                idx = np.triu_indices(k, k=1)
                cache[k] = idx
            ii, jj = cache[k]
            E.append(np.repeat(e[ii], 1))
            E.append(e[ii])
            J.append(e[jj])
            J.append(e[jj])
            W.append(np.full(len(ii), float(2 ** (k - 2))))
        if not E:
            return (np.zeros(0, np.int64), np.zeros(0, np.int64), np.zeros(0))
        return np.concatenate(E), np.concatenate(J), np.concatenate(W)
    # plain: only the first pair of each hyperedge matters
    for e in edges:
        if len(e) >= 2:
            E.append(e[0])
            J.append(e[1])
    if not E:
        return (np.zeros(0, np.int64), np.zeros(0, np.int64), np.zeros(0))
    w = np.ones(len(E))
    return np.array(E), np.array(J), w


def hypergraph_cut(edges, x):
    """Exact number of cut hyperedges for labels x in {0,1}^n."""
    cut = 0
    for e in edges:
        v = x[e[0]]
        for u in e[1:]:
            if x[u] != v:
                cut += 1
                break
    return cut


def graph_cut(ei, ej, x):
    """Number of cut graph edges."""
    return int((x[ei] != x[ej]).sum())
